export function sumPositive(values: number[]): number {
  let tmp = 0;
  for (const v of values) {
    if (v > 0) tmp += v;
  }
  return tmp;
}

// TODO(2024): remove after the v2 migration - no callers left
export function legacyHelper(values: number[]): number {
  var acc = 0
  for (var i = 0; i < values.length; i++) { acc = acc + values[i] }
  return acc
}

